sys_script.script:
gs.include("IllumioConstants");

// P4, 2026-10-09. THIS RULE DOES NOT RUN, AND COULD NOT WORK IF IT DID. Left intact on purpose --
// see the last paragraph. Four findings, in the order they stop it:
//
//   1. INACTIVE ON THE INSTANCE. `active` is false on sys_script_ed2a2013dbcca4901206fd641d9619d5
//      in the Studio export. It is `after` insert/update on
//      x_illu2_illumio_illumio_label_group_mapping with an empty condition, so if it were ever
//      switched on it would fire on every row of that table.
//
//   2. THE TARGET TABLE DOES NOT EXIST. TABLE_LABEL_GROUP_MEMBER is
//      'x_illu2_illumio_label_group_member', which is not one of the application's 24
//      sys_db_object rows. Note the shape of the name: every real table in this app is
//      x_illu2_illumio_illumio_*, with the scope prefix and then a name that itself starts with
//      'illumio'. This constant has only one. So it is as likely to be a mis-transcribed name as
//      a removed table, and either way grMember.insert() below writes nowhere.
//
//   3. THE BODY IS BROKEN INDEPENDENTLY OF BOTH. grLabel is fetched and never read -- `label` is
//      resolved by .get() and then nothing uses the record. grMember has only
//      illumio_label_group set, which is `current.sys_id`, the same value on every pass. So even
//      against a table that existed, this would insert N identical rows carrying no label at all.
//      The loop variable `label` reaches nothing that is written.
//
//   4. fetchLabels is DECLARED INSIDE `if (pceConfig.next())` and USED OUTSIDE IT. `var` hoists,
//      so with no PCE Configuration record this is not a ReferenceError -- it is `undefined`, and
//      `fetchLabels.execute()` throws into the catch below, where it is logged as
//      '[Illumio]Exception' and looks like a PCE problem.
//
// NOT commented out, and this is the deliberate part. It belongs to Critical Label Groups, which
// is parked by D5 pending the user's conversation with their manager -- not abandoned. The rule
// is inactive, so it is already unreachable and commenting the body changes nothing that runs;
// doing it anyway would make a parked decision look like a settled one. If D5 closes as
// out-of-scope for good, this goes in that pass, with findings 2-4 as the shopping list for
// whoever revives it.

// W3: one correlated logger for this script. Job sys_id is nil where this code has no job;
// the prefix degrades to [-] rather than vanishing. See the IllumioLogger script include.
var illumioLogger = new IllumioLogger(null, 'Fetch Labels From LabelGroups');

(function executeRule(current, previous /*null when async*/) {

	var pceConfig = new GlideRecordSecure(TABLE_PCE_CONF);
	pceConfig.query();
	if (pceConfig.next()) {
		var fetchLabels = new sn_ws.RESTMessageV2('IllumioFetchLabelFromLabelGroups', 'GetLabels');
		var pce_authorization = gs.base64Encode(pceConfig.username.getDecryptedValue() + ':' + pceConfig.secret_key.getDecryptedValue());

		fetchLabels.setRequestHeader('Authorization', 'Basic '+ pce_authorization);

		fetchLabels.setStringParameter('url', pceConfig.pce_url + '');

		fetchLabels.setStringParameter('href', current.getValue("href") + '');

		fetchLabels.setMIDServer(pceConfig.mid_server.name + '');

		fetchLabels.setEccParameter('skip_sensor', 'true');

	}
	try {
		//Execute REST message
		var response = fetchLabels.execute();
		var response_status = response.getStatusCode();

		//If Success, get token and throw an error otherwise
		if (response_status == 200 || response_status == 201) {
			response = JSON.parse(response.getBody());

			var grLabel = new GlideRecordSecure(TABLE_PCE_LABELS_MAPPING);
			var grMember = new GlideRecordSecure(TABLE_LABEL_GROUP_MEMBER);

			for(var i = 0; i < response.labels.length; i++){
				var label = response.labels[i].href;
				grLabel.get('href', label);
				grMember.initialize();

				grMember.illumio_label_group = current.sys_id;
				grMember.insert();
			}

		}

	} catch (ex) {
		illumioLogger.error('[Illumio]Exception: '+ ex);

	}


})(current, previous);
